#include "pc/fs/pc_fs.h"

#ifdef PC_PORT

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

s_PcFsEntry g_PcFsQueue[PC_FS_MAX_QUEUE] = {0};
int g_PcFsQueueLen = 0;

static char s_AssetsRoot[PC_FS_MAX_PATH] = {0};
void* FS_BUFFER_0_PTR = NULL;
void* FS_BUFFER_16_PTR = NULL;
void* g_FsExtraBuffers[32] = {0};
s_PcOverlay g_PcOverlays[PcOverlay_Count] = {0};

// File table path resolution — mirrors main/fileinfo.c g_FileTable logic
// On PC we trust e_FsFile → assets path mapping generated by silentassets
static const char* s_FsFileToPath(e_FsFile id) {
    // Minimal table: only the files boot needs. Full table is generated
    // from g_FileTable at extraction time and written to assets/USA/filemap.json
    // by tools/silentassets/extract.py. We lazy-load that JSON here.
    static bool loaded = false;
    static char* paths[4096] = {0};
    if (!loaded) {
        char mapPath[PC_FS_MAX_PATH];
        snprintf(mapPath, sizeof(mapPath), "%s/filemap.json", s_AssetsRoot);
        FILE* f = fopen(mapPath, "r");
        if (f) {
            // Very small JSON parser: expects {"0": "1ST/BODYPROG.BIN", ...}
            // For now we rely on fallback naming.
            fclose(f);
        }
        loaded = true;
    }
    (void)paths;
    return NULL;
}

void PcFs_Init(const char* assetsRoot) {
    strncpy(s_AssetsRoot, assetsRoot, sizeof(s_AssetsRoot)-1);
    FS_BUFFER_0_PTR = malloc(0x80000);
    FS_BUFFER_16_PTR = malloc(0x80000);
    for (int i = 0; i < 32; i++) g_FsExtraBuffers[i] = malloc(0x40000);
    // Allocate overlay slots
    printf("PcFs: assets root = %s\n", s_AssetsRoot);
}

void PcFs_Shutdown(void) {
    free(FS_BUFFER_0_PTR);
    free(FS_BUFFER_16_PTR);
    for (int i = 0; i < 32; i++) free(g_FsExtraBuffers[i]);
    for (int i = 0; i < PcOverlay_Count; i++) {
        if (g_PcOverlays[i].base) {
            // Don't free BODYPROG if it was handed to game code; leak at shutdown is fine
        }
    }
}

static char* resolve_path(e_FsFile file) {
    // Try s_FsFileToPath first, fallback to asset dir listing
    const char* known = s_FsFileToPath(file);
    if (known) {
        static char buf[PC_FS_MAX_PATH];
        snprintf(buf, sizeof(buf), "%s/%s", s_AssetsRoot, known);
        return buf;
    }
    // Fallback: enumerate known boot files
    static char fallback[PC_FS_MAX_PATH];
    // Common files needed to boot to menu
    switch (file) {
        case FILE_1ST_BODYPROG_BIN: snprintf(fallback, sizeof(fallback), "%s/1ST/BODYPROG.BIN", s_AssetsRoot); break;
        case FILE_1ST_B_KONAMI_BIN: snprintf(fallback, sizeof(fallback), "%s/1ST/B_KONAMI.BIN", s_AssetsRoot); break;
        case FILE_1ST_KONAMI2_TIM:  snprintf(fallback, sizeof(fallback), "%s/1ST/KONAMI2.TIM", s_AssetsRoot); break;
        case FILE_1ST_2ZANKO_E_TIM: snprintf(fallback, sizeof(fallback), "%s/1ST/2ZANKO_E.TIM", s_AssetsRoot); break;
        default: {
            // Generic: try VIN/MAP* and SND/*
            snprintf(fallback, sizeof(fallback), "%s/unknown_%d.bin", s_AssetsRoot, (int)file);
            break;
        }
    }
    return fallback;
}

void* PcFs_LoadFile(e_FsFile file, size_t* outSize) {
    char* path = resolve_path(file);
    FILE* f = fopen(path, "rb");
    if (!f) {
        // Try alternate locations
        return NULL;
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    void* buf = malloc(sz);
    if (fread(buf, 1, sz, f) != (size_t)sz) {
        free(buf); fclose(f); return NULL;
    }
    fclose(f);
    if (outSize) *outSize = sz;
    return buf;
}

void PcFs_FreeFile(void* data) { free(data); }

const char* PcFs_GetPath(e_FsFile file) { return resolve_path(file); }
size_t PcFs_GetSize(e_FsFile file) {
    char* path = resolve_path(file);
    FILE* f = fopen(path, "rb");
    if (!f) return 0;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fclose(f);
    return sz;
}

// Queue — async stub (synchronous for now)
void PcFs_QueueStartRead(e_FsFile file, int bufferId) {
    if (g_PcFsQueueLen >= PC_FS_MAX_QUEUE) return;
    s_PcFsEntry* e = &g_PcFsQueue[g_PcFsQueueLen++];
    e->fileId = file;
    e->buffer = (bufferId == FS_BUFFER_0) ? FS_BUFFER_0_PTR :
                (bufferId == FS_BUFFER_16) ? FS_BUFFER_16_PTR :
                g_FsExtraBuffers[bufferId & 31];
    e->state = PcFsState_Loading;
    // Synchronous load for now
    size_t sz = 0;
    void* data = PcFs_LoadFile(file, &sz);
    if (data && e->buffer) {
        memcpy(e->buffer, data, sz);
        e->size = sz;
        e->state = PcFsState_Ready;
        free(data);
    } else {
        e->state = PcFsState_Error;
    }
}

void PcFs_QueueStartReadTim(e_FsFile file, int bufferId, void* imageDesc) {
    (void)imageDesc;
    PcFs_QueueStartRead(file, bufferId);
}

void PcFs_Update(void) {
    // Compact completed entries (PSX does this in VSync)
    int w = 0;
    for (int i = 0; i < g_PcFsQueueLen; i++) {
        if (g_PcFsQueue[i].state != PcFsState_Ready) {
            g_PcFsQueue[w++] = g_PcFsQueue[i];
        }
    }
    g_PcFsQueueLen = w;
}

int PcFs_GetQueueLength(void) { return g_PcFsQueueLen; }
bool PcFs_ChunksLoad(void) { return g_PcFsQueueLen == 0; }

// Compatibility aliases — so src/main/fsqueue.c can just call these
void Fs_QueueInitialize(void) { g_PcFsQueueLen = 0; }
void Fs_QueueStartRead(e_FsFile file, s32 bufferId) { PcFs_QueueStartRead(file, bufferId); }
void Fs_QueueStartReadTim(e_FsFile file, s32 bufferId, void* img) { PcFs_QueueStartReadTim(file, bufferId, img); }
void Fs_QueueUpdate(void) { PcFs_Update(); }
int  Fs_QueueGetLength(void) { return PcFs_GetQueueLength(); }
bool Fs_QueueChunksLoad(void) { return PcFs_ChunksLoad(); }
s32  Fs_QueueGetFileSize(e_FsFile file) { return (s32)PcFs_GetSize(file); }
void Fs_QueueWaitForEmpty(void) { while (!PcFs_ChunksLoad()) PcFs_Update(); }

#endif
